export const TEMPLATE = "\n<div class=\"studio-top\"><div><h2>수묵설 <span>STUDIO</span></h2><p class=\"intro\">흐르는 물감, 서로 다른 시간의 눈.</p></div><label class=\"form-check theme-switch\"><input data-control=\"darkMode\" type=\"checkbox\"/>다크 모드</label></div>\n<div class=\"studio-toolbar\">\n<label class=\"form-label ratio-label\">화면 비율<select aria-label=\"화면 비율\" class=\"form-select\" data-control=\"aspectPreset\"><option value=\"auto\">자동 · 화면에 맞춤</option><option value=\"8:5\">8:5 · 원본</option><option value=\"16:9\">16:9 · 와이드</option><option value=\"21:9\">21:9 · 시네마</option><option value=\"4:3\">4:3</option><option value=\"1:1\">1:1 · 정사각</option><option value=\"9:16\">9:16 · 세로</option><option value=\"custom\">직접 설정</option></select></label>\n<div class=\"custom-aspect\" data-control=\"customAspect\" hidden=\"\"><label>가로<input data-control=\"aspectWidth\" max=\"32\" min=\"1\" step=\".1\" type=\"number\" value=\"8\"/></label><span>:</span><label>세로<input data-control=\"aspectHeight\" max=\"32\" min=\"1\" step=\".1\" type=\"number\" value=\"5\"/></label><button class=\"btn\" data-control=\"applyAspect\" type=\"button\">적용</button></div>\n<div class=\"file-actions\"><button class=\"btn\" data-control=\"export\" type=\"button\">설정 내보내기</button><button class=\"btn\" data-control=\"exportHTML\" type=\"button\">보기 전용 HTML 내보내기</button><button class=\"btn\" data-control=\"import\" type=\"button\">불러오기</button><button class=\"btn\" data-control=\"reset\" type=\"button\">초기 설정</button><input accept=\"application/json,.json\" data-control=\"importFile\" hidden=\"\" type=\"file\"/></div>\n</div>\n<div class=\"snow-stage\" data-control=\"stage\">\n<canvas tabindex=\"0\" aria-label=\"입자의 움직임을 다섯 깊이층의 밀도로 그린 수묵 풍경. 그리는 방식을 바꾸면 같은 입자를 기존 이미지 또는 물리 위치로 비교할 수 있습니다. 눈송이를 누르면 깊이와 층별 기여도를 표시합니다.\" class=\"cursor-interaction\" role=\"img\">같은 물리 입자를 다섯 개 깊이층에서 합성한 검은 눈.</canvas>\n<div class=\"snow-exit\" aria-label=\"보기 전용 조작\"><button class=\"btn\" data-control=\"exitFullscreen\" type=\"button\">돌아가기</button><button class=\"btn\" data-control=\"viewerFullscreen\" type=\"button\" hidden>전체화면</button></div>\n<div class=\"snow-view-message text-small\" data-control=\"viewMessage\" hidden=\"\" role=\"status\"></div>\n</div>\n<div class=\"viz-controls\">\n<label class=\"form-check\"><input data-control=\"scrollWind\" type=\"checkbox\" checked/>페이지 스크롤 연동</label>\n<label class=\"form-label\">스크롤 움직임<select class=\"form-select\" data-control=\"scrollMode\"><option value=\"camera\" selected>카메라 이동 · 스크롤 반대 방향 (기본)</option><option value=\"cameraSame\">카메라 이동 · 스크롤 같은 방향</option><option value=\"speed\">원래 방식 · 아래 가속 / 위 감속</option><option value=\"speedBoth\">양방향 낙하 가속</option></select></label>\n<label class=\"form-check\" data-control=\"scrollBothWrap\" hidden><input data-control=\"scrollBothDirections\" type=\"checkbox\" checked/>양방향 스크롤 모두 가속</label>\n<label class=\"form-label\">스크롤 반응 <output data-control=\"scrollStrength-value\">1.0×</output>\n<input aria-label=\"스크롤 반응\" class=\"form-range\" data-control=\"scrollStrength\" type=\"range\" min=\"0\" max=\"5\" step=\"0.1\" value=\"1\"/></label>\n<button class=\"btn\" data-control=\"windLeft\" type=\"button\">왼쪽 바람</button>\n<button class=\"btn\" data-control=\"windRight\" type=\"button\">오른쪽 바람</button>\n<label class=\"form-check\"><input class=\"form-check-input\" data-control=\"pointerWind\" type=\"checkbox\"/><span class=\"form-check-label\">마우스 좌우 움직임과 연동</span></label>\n<button aria-pressed=\"false\" class=\"btn\" data-control=\"pause\" type=\"button\">일시정지</button>\n<button aria-pressed=\"false\" class=\"btn\" data-control=\"observe\" type=\"button\">눈송이 관찰</button>\n<button aria-pressed=\"false\" class=\"btn\" data-control=\"fullscreen\" type=\"button\">그림만 전체화면</button>\n</div>\n<div class=\"viz-controls\">\n<label class=\"form-check\"><input data-control=\"scrollClouds\" type=\"checkbox\" checked/>구름도 스크롤에 반응</label>\n<label class=\"form-label\" data-for=\"scrollCloudStrength\">구름 스크롤 강도 <output data-control=\"scrollCloudStrength-value\">0.35×</output>\n<input class=\"form-range\" data-control=\"scrollCloudStrength\" type=\"range\" min=\"0\" max=\"2.5\" step=\"0.05\" value=\"0.35\"/></label>\n<label class=\"form-label\" data-for=\"scrollBlur\">스크롤 모션 블러 <output data-control=\"scrollBlur-value\">0.00×</output>\n<input class=\"form-range\" data-control=\"scrollBlur\" type=\"range\" min=\"0\" max=\"3\" step=\"0.05\" value=\"0\"/></label>\n</div>\n<p class=\"text-small\">구름은 선택한 스크롤 방향을 따르며, 강도는 눈과 별도로 조절합니다. 스크롤 블러 0배는 기존 표현을 유지하고, 높이면 눈과 움직이는 구름에 잔상을 더합니다. 스크롤을 멈추면 추가 블러만 서서히 사라집니다.</p>\n\n<div class=\"text-small tabular-nums\" data-control=\"inspect\" hidden=\"\"></div>\n<div aria-live=\"polite\" class=\"studio-message\" data-control=\"message\" hidden=\"\" role=\"status\"></div>\n<div class=\"controls-grid\"><div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"snowAmount\">눈 양 <output data-control=\"snowAmount-value\">100%</output>\n<input class=\"form-range\" data-control=\"snowAmount\" data-describedby=\"amount-help\" max=\"200\" min=\"0\" step=\"10\" type=\"range\" value=\"100\">\n</input></label>\n</div><div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"snowSize\">눈 크기 <output data-control=\"snowSize-value\">1.00×</output>\n<input class=\"form-range\" data-control=\"snowSize\" max=\"200\" min=\"50\" step=\"5\" type=\"range\" value=\"100\">\n</input></label>\n<label class=\"form-label\" data-for=\"opacity\">눈 불투명도 <output data-control=\"opacity-value\">100%</output>\n<input class=\"form-range\" data-control=\"opacity\" max=\"100\" min=\"0\" step=\"1\" type=\"range\" value=\"100\">\n</input></label>\n</div><div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"shortExposure\">선명하게 잡히는 눈 · 기준 <output data-control=\"shortExposure-value\">60%</output>\n<input class=\"form-range\" data-control=\"shortExposure\" max=\"100\" min=\"0\" step=\"5\" type=\"range\" value=\"60\">\n</input></label>\n<label class=\"form-check form-switch\" data-for=\"shortAuto\">\n<input class=\"form-check-input\" data-control=\"shortAuto\" type=\"checkbox\"/>\n<span class=\"form-check-label\">선명 비율 자동 변화</span>\n</label>\n</div><div class=\"text-small\" data-control=\"amount-help\">0% 없음 · 100% 기존 양 · 200% 두 배. 재생 중에는 눈이 서서히 늘거나 줄어듭니다.</div><div class=\"text-small tabular-nums\" data-control=\"shortActual\" hidden=\"\">현재 60% · 35–85% · 10초 주기</div></div>\n<details class=\"new-section\" open=\"\"><summary>색상과 대비</summary>\n<div class=\"color-controls\"><label class=\"form-label\">눈 색<input aria-label=\"눈 색\" data-control=\"snowColor\" type=\"color\" value=\"#090e13\"/></label><label class=\"form-label\">배경색<input aria-label=\"배경색\" data-control=\"backgroundColor\" type=\"color\" value=\"#ffffff\"/></label><label class=\"form-label\">물감 색<input aria-label=\"물감 색\" data-control=\"washColor\" type=\"color\" value=\"#4f87ad\"/></label>\n<label class=\"form-label\">눈·배경 색 대비<output data-control=\"contrast-value\">100%</output><input aria-label=\"눈·배경 색 대비\" class=\"form-range\" data-control=\"contrast\" max=\"200\" min=\"0\" step=\"5\" type=\"range\" value=\"100\"/></label></div>\n<p class=\"text-small\">대비 100%는 선택한 눈 색을 그대로 사용합니다. 불투명도와 별도로 색 차이를 조절합니다. 다크 모드는 야간 팔레트를 적용하며, 색은 이후 자유롭게 바꿀 수 있습니다.</p>\n</details>\n<details class=\"new-section\" open=\"\"><summary>카메라 깊이와 근접 눈</summary>\n<div class=\"viz-controls\"><label class=\"form-label\">일반 눈 z 최소<output data-control=\"zMin-value\">2.6</output><input aria-label=\"일반 눈 z 최소\" class=\"form-range\" data-control=\"zMin\" max=\"20\" min=\"0.5\" step=\"0.1\" type=\"range\" value=\"2.6\"/></label><label class=\"form-label\">일반 눈 z 최대<output data-control=\"zMax-value\">10.8</output><input aria-label=\"일반 눈 z 최대\" class=\"form-range\" data-control=\"zMax\" max=\"40\" min=\"1\" step=\"0.1\" type=\"range\" value=\"10.8\"/></label></div>\n<div class=\"viz-controls\"><label class=\"form-check\"><input checked=\"\" data-control=\"nearLens\" type=\"checkbox\"/>드문 렌즈 앞 통과</label><label class=\"form-label\">근접 눈 비율<output data-control=\"nearFraction-value\">0.8%</output><input aria-label=\"근접 눈 비율\" class=\"form-range\" data-control=\"nearFraction\" max=\"3\" min=\"0\" step=\"0.1\" type=\"range\" value=\"0.8\"/></label><label class=\"form-label\">근접 눈의 최저 z<output data-control=\"nearZ-value\">0.45</output><input aria-label=\"근접 눈의 최저 z\" class=\"form-range\" data-control=\"nearZ\" max=\"2\" min=\"0.15\" step=\"0.05\" type=\"range\" value=\"0.45\"/></label></div>\n<p class=\"text-small\">z가 작을수록 카메라에 가깝습니다. 근접 눈만 일반 범위보다 앞을 통과합니다. 크기·이동 속도·초점 흐림이 연속적으로 변하며, 비율 변경은 화면 밖에서 새 경로를 선택할 때 반영됩니다.</p>\n</details>\n<details class=\"legacy-settings\"><summary>모션 블러·레이어·필름·수채화 설정</summary>\n<div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"motionStyle\">모션 블러 방식\n      <select class=\"form-select\" data-control=\"motionStyle\">\n<option selected=\"\" value=\"swept\">이동 경로 잔상 · 복원</option>\n<option value=\"compact\">직전 둥근 번짐 · 비교</option>\n</select>\n</label>\n</div>\n<div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"layerTiming\">층 갱신\n      <select class=\"form-select\" data-control=\"layerTiming\">\n<option value=\"sync\">동시에 갱신</option>\n<option value=\"stagger\">층마다 시간차</option>\n<option selected=\"\" value=\"trail\">층마다 시간차 + 짧은 잔상</option>\n</select>\n</label>\n<label class=\"form-label\" data-for=\"stagger\">층 시간차 <output data-control=\"stagger-value\">100%</output>\n<input class=\"form-range\" data-control=\"stagger\" max=\"100\" min=\"0\" step=\"5\" type=\"range\" value=\"100\">\n</input></label>\n</div>\n<div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"renderer\">그리는 방식\n      <select class=\"form-select\" data-control=\"renderer\">\n<option selected=\"\" value=\"field\">밀도에서 그리기 · 5개 층</option>\n<option value=\"sprites\">기존 · 눈송이별 이미지</option>\n<option value=\"particles\">물리 입자 위치 · 진단</option>\n</select>\n</label>\n<label class=\"form-label\" data-for=\"layer\">깊이층 보기\n      <select class=\"form-select\" data-control=\"layer\">\n<option selected=\"\" value=\"-1\">전체 합성</option>\n<option value=\"0\">1 · 가장 먼 층</option>\n<option value=\"1\">2 · 먼 층</option>\n<option value=\"2\">3 · 중간 층</option>\n<option value=\"3\">4 · 가까운 층</option>\n<option value=\"4\">5 · 가장 가까운 층</option>\n</select>\n</label>\n</div>\n<div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"look\">영화 느낌\n      <select class=\"form-select\" data-control=\"look\">\n<option selected=\"\" value=\"original\">수채화 원본</option>\n<option value=\"cinema\">시네마 · 24fps</option>\n<option value=\"vintage\">옛 필름 · 18fps</option>\n<option value=\"anime\">애니메이션 · 12fps</option>\n<option value=\"dream\">몽환 잔상 · 30fps</option>\n</select>\n</label>\n<label class=\"form-label\" data-for=\"fps\">층별 촬영 프레임 <output data-control=\"fps-value\">24fps</output>\n<input aria-label=\"층별 촬영 프레임\" class=\"form-range\" data-control=\"fps\" max=\"30\" min=\"0\" step=\"1\" type=\"range\" value=\"24\"/>\n</label>\n</div>\n<div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"softSnowMix\">형태 유지 블러 비율 <output data-control=\"softSnowMix-value\">35%</output>\n<input class=\"form-range\" data-control=\"softSnowMix\" max=\"100\" min=\"0\" step=\"5\" type=\"range\" value=\"35\">\n</input></label>\n<label class=\"form-check form-switch\" data-for=\"softSnowBlur\">\n<input checked=\"\" class=\"form-check-input\" data-control=\"softSnowBlur\" type=\"checkbox\">\n<span class=\"form-check-label\">눈 형태를 유지하는 블러</span>\n</input></label>\n</div>\n<div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"vintageMix\">옛 필름 비율 <output data-control=\"vintageMix-value\">0%</output>\n<input class=\"form-range\" data-control=\"vintageMix\" max=\"100\" min=\"0\" step=\"1\" type=\"range\" value=\"0\">\n</input></label>\n<label class=\"form-check form-switch\" data-for=\"smoothGrain\">\n<input class=\"form-check-input\" data-control=\"smoothGrain\" type=\"checkbox\">\n<span class=\"form-check-label\">필름 노이즈 부드럽게 교체</span>\n</input></label>\n</div>\n<div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"temporal\">프레임 연결\n      <select class=\"form-select\" data-control=\"temporal\">\n<option value=\"soft\">부드러운 셔터 + 프레임 혼합</option>\n<option selected=\"\" value=\"shutter\">부드러운 셔터 · 프레임 유지</option>\n<option value=\"legacy\">부드러운 방향성 블러 · 프레임 유지</option>\n</select>\n</label>\n</div>\n<div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"finish\">표면과 빛\n      <select class=\"form-select\" data-control=\"finish\">\n<option value=\"none\">원본</option>\n<option value=\"watercolor\">젖은 수채화</option>\n<option value=\"diffusion\">소프트 렌즈</option>\n<option selected=\"\" value=\"combined\">수채화 + 렌즈</option>\n</select>\n</label>\n<label class=\"form-label\" data-for=\"shaderStrength\">효과 강도 <output data-control=\"shaderStrength-value\">70%</output>\n<input class=\"form-range\" data-control=\"shaderStrength\" max=\"100\" min=\"0\" step=\"1\" type=\"range\" value=\"70\">\n</input></label>\n</div>\n<details>\n<summary>먹·수채화·움직임 설정</summary>\n<div class=\"viz-controls\">\n<label class=\"form-label\" data-for=\"trail\">이전 모습의 비율 <output data-control=\"trail-value\">25%</output>\n<input class=\"form-range\" data-control=\"trail\" max=\"55\" min=\"0\" step=\"5\" type=\"range\" value=\"25\">\n</input></label>\n<label class=\"form-label\" data-for=\"spread\">먹 번짐 <output data-control=\"spread-value\">30%</output>\n<input class=\"form-range\" data-control=\"spread\" max=\"100\" min=\"0\" step=\"1\" type=\"range\" value=\"30\">\n</input></label>\n<label class=\"form-label\" data-for=\"flow\">물감 흐름 <output data-control=\"flow-value\">70%</output>\n<input class=\"form-range\" data-control=\"flow\" max=\"100\" min=\"0\" step=\"1\" type=\"range\" value=\"70\">\n</input></label>\n<label class=\"form-label\" data-for=\"pigment\">안료와 종이 결 <output data-control=\"pigment-value\">65%</output>\n<input class=\"form-range\" data-control=\"pigment\" max=\"100\" min=\"0\" step=\"1\" type=\"range\" value=\"65\"/>\n</label>\n<label class=\"form-label\" data-for=\"diffusion\">렌즈 확산 <output data-control=\"diffusion-value\">55%</output>\n<input class=\"form-range\" data-control=\"diffusion\" max=\"100\" min=\"0\" step=\"1\" type=\"range\" value=\"55\"/>\n</label>\n<label class=\"form-label\" data-for=\"coverage\">셔터 길이 <output data-control=\"coverage-value\">100%</output>\n<input class=\"form-range\" data-control=\"coverage\" max=\"150\" min=\"40\" step=\"5\" type=\"range\" value=\"100\"/>\n</label>\n<label class=\"form-label\" data-for=\"transition\">프레임 전환 구간 <output data-control=\"transition-value\">80%</output>\n<input class=\"form-range\" data-control=\"transition\" max=\"100\" min=\"15\" step=\"5\" type=\"range\" value=\"80\"/>\n</label>\n<label class=\"form-label\" data-for=\"film\">필름 효과 강도 <output data-control=\"film-value\">70%</output>\n<input class=\"form-range\" data-control=\"film\" disabled=\"\" max=\"100\" min=\"0\" step=\"1\" type=\"range\" value=\"70\"/>\n</label>\n<label class=\"form-label\" data-for=\"zmotion\">앞뒤 이동 <output data-control=\"zmotion-value\">1.0×</output>\n<input class=\"form-range\" data-control=\"zmotion\" max=\"2.5\" min=\"0\" step=\"0.1\" type=\"range\" value=\"1\"/>\n</label>\n<label class=\"form-label\" data-for=\"focus\">초점 위치 <output data-control=\"focus-value\">6.0</output>\n<input class=\"form-range\" data-control=\"focus\" max=\"40\" min=\"0.2\" step=\"0.1\" type=\"range\" value=\"6\"/>\n</label>\n<label class=\"form-label\" data-for=\"aperture\">초점 흐림 <output data-control=\"aperture-value\">1.0×</output>\n<input class=\"form-range\" data-control=\"aperture\" max=\"2.5\" min=\"0\" step=\"0.1\" type=\"range\" value=\"1\"/>\n</label>\n<label class=\"form-label\" data-for=\"speed\">눈 속도 <output data-control=\"speed-value\">1.0×</output>\n<input class=\"form-range\" data-control=\"speed\" max=\"2.5\" min=\"0.5\" step=\"0.1\" type=\"range\" value=\"1\"/>\n</label>\n<label class=\"form-label\" data-for=\"blur\">모션 블러 <output data-control=\"blur-value\">1.0×</output>\n<input class=\"form-range\" data-control=\"blur\" max=\"2.5\" min=\"0\" step=\"0.1\" type=\"range\" value=\"1\"/>\n</label>\n<label class=\"form-label\" data-for=\"background\">배경 움직임 <output data-control=\"background-value\">1.0×</output>\n<input class=\"form-range\" data-control=\"background\" max=\"2.5\" min=\"0\" step=\"0.1\" type=\"range\" value=\"1\"/>\n</label>\n<label class=\"form-label\" data-for=\"cloudMorph\">구름 모양 변화 <output data-control=\"cloudMorph-value\">45%</output>\n<input class=\"form-range\" data-control=\"cloudMorph\" max=\"100\" min=\"0\" step=\"5\" type=\"range\" value=\"45\"/>\n</label>\n</div>\n</details>\n</details>\n<div class=\"text-small\" data-control=\"fallback\" hidden=\"\" role=\"status\"></div><span aria-live=\"polite\" class=\"sr-only\" data-control=\"status\">재생 중</span>\n";
